#!/usr/bin/env bash
# verify_round.sh — machine checks for the Messages repo. No narrative, no scores.
# Usage (from the repo root):  bash scripts/verify_round.sh
# Exit code 0 = all FAIL-level checks passed. Anything else = fix before reporting.
# DO NOT EDIT THIS FILE. The reviewer runs the same file on the pushed commit.

cd "$(git rev-parse --show-toplevel)" || exit 2
FAILS=0; WARNS=0
UI=app/src/main/kotlin/com/messages/app/ui
pass(){ printf "PASS  %s\n" "$1"; }
fail(){ printf "FAIL  %s\n" "$1"; FAILS=$((FAILS+1)); }
warn(){ printf "WARN  %s\n" "$1"; WARNS=$((WARNS+1)); }

echo "commit: $(git rev-parse --short HEAD)  branch: $(git rev-parse --abbrev-ref HEAD)"
echo "------------------------------------------------------------"

# 1. Synthetic / test-data code must not exist in production source sets
n=$(git grep -n "SyntheticStressData\|injectSyntheticStressData\|Rostova\|ReactionStore\|STRESS_THREAD" -- app/src/main design-system/src/main 2>/dev/null | wc -l)
[ "$n" -eq 0 ] && pass "1  no synthetic/test-data/reaction code in app/src/main" || fail "1  $n reference(s) to synthetic data / ReactionStore in production source"

# 2. Nothing may run seeding at startup
n=$(git grep -n "inject.*Stress\|seed.*onCreate\|SeedData" -- app/src/main 2>/dev/null | wc -l)
[ "$n" -eq 0 ] && pass "2  no seeding hooks in app/src/main" || fail "2  seeding hook found in app/src/main ($n)"

# 3. Every exported receiver in debug/benchmark manifests must carry a permission
bad=0
for m in app/src/debug/AndroidManifest.xml app/src/benchmark/AndroidManifest.xml; do
  [ -f "$m" ] || continue
  c=$(python3 - "$m" <<'PY'
import sys,re
s=open(sys.argv[1]).read()
bad=0
for el in re.findall(r'<receiver\b.*?>',s,flags=re.S):
    if 'android:exported="true"' in el and 'android:permission=' not in el: bad+=1
print(bad)
PY
)
  bad=$((bad+c))
done
[ "$bad" -eq 0 ] && pass "3  every exported debug/benchmark receiver has android:permission" || fail "3  $bad exported receiver(s) without android:permission"

# 4. Wipe must require an explicit confirmation string
f=$(git ls-files | grep "SeedDataReceiver.kt" | head -1)
if [ -n "$f" ]; then
  grep -q "WIPE_ALL_DATA" "$f" && pass "4  SeedDataReceiver requires confirm=WIPE_ALL_DATA" || fail "4  SeedDataReceiver wipe has no WIPE_ALL_DATA confirmation"
else
  pass "4  no SeedDataReceiver in repo (nothing to confirm)"
fi

# 5. Benchmark build type isolation
if grep -q 'create("benchmark")' app/build.gradle.kts; then
  grep -A12 'create("benchmark")' app/build.gradle.kts | grep -q 'applicationIdSuffix' && pass "5a benchmark build has applicationIdSuffix" || fail "5a benchmark build lacks applicationIdSuffix"
  grep -A8 'getByName("benchmark")' app/build.gradle.kts | grep -q 'src/debug/kotlin' && fail "5b benchmark source set still compiles all of src/debug/kotlin" || pass "5b benchmark does not compile src/debug/kotlin"
else
  pass "5  no benchmark build type"
fi

# 6. Design rules
n=$(grep -rn 'Color(0x' --include=*.kt $UI | grep -v -e VaultTheme -e ChatStyle -e SenderBadge | wc -l)
[ "$n" -eq 0 ] && pass "6  no hardcoded Color(0x...) in screens" || fail "6  $n hardcoded Color(0x...) in screens"
n=$(grep -rn 'Brush.linearGradient\|\.blur(\|RenderEffect' --include=*.kt app/src/main design-system/src/main | grep -v -e secret -e ChatStyle -e ChatScreen | wc -l)
[ "$n" -eq 0 ] && pass "7  no gradients/blur outside Vault + chat wallpaper" || fail "7  $n gradient/blur use(s) outside Vault/chat wallpaper"
n=$(grep -rn 'Text("' --include=*.kt app/src/main/kotlin | grep -v -e newPlainText -e setContentText | wc -l)
[ "$n" -eq 0 ] && pass "8  no literal strings in Text()" || fail "8  $n literal Text(\"...\") string(s)"
bad=$(grep -rho 'RoundedCornerShape([0-9]*\.dp)' --include=*.kt app/src/main/kotlin design-system | sed 's/.*Shape(//; s/\.dp.*//' | sort -un | grep -vx -e 4 -e 8 -e 12 -e 20 -e 24 -e 28 -e 32 | tr '\n' ' ')
[ -z "$bad" ] && pass "9  corner radii within {4,8,12,20,24,28,32}" || fail "9  disallowed corner radii: $bad"

# 10. Baseline profile must be generated, not hand-written wildcards
if [ -f app/src/main/baseline-prof.txt ]; then
  n=$(grep -c '\*\*' app/src/main/baseline-prof.txt)
  [ "$n" -eq 0 ] && pass "10 baseline-prof.txt has no wildcard rules ($(wc -l < app/src/main/baseline-prof.txt) lines)" || fail "10 baseline-prof.txt contains $n wildcard rule(s)"
fi

# 11. Performance evidence integrity
if [ -d docs/reviews/perf ]; then
  python3 - <<'PY'
import json,glob,sys,os
bad=[];real=0
for f in sorted(glob.glob('docs/reviews/perf/*.json')):
    try: d=json.load(open(f))
    except Exception: bad.append(os.path.basename(f)+' (invalid JSON)'); continue
    if isinstance(d,dict) and 'benchmarks' in d and 'context' in d: real+=1
    else: bad.append(os.path.basename(f))
print("PASS  11 all perf JSON files are genuine androidx benchmark output (%d)"%real if not bad and real else
      "FAIL  11 perf JSON not in androidx format (hand-made or invalid): %s | genuine files: %d"%(', '.join(bad) or 'none',real))
sys.exit(0 if (not bad and real) else 3)
PY
  [ $? -ne 0 ] && FAILS=$((FAILS+1))
  [ -f docs/reviews/perf/device.txt ] && pass "12 docs/reviews/perf/device.txt exists" || fail "12 docs/reviews/perf/device.txt missing"
  # every P50/P99 value quoted in the report must exist in a genuine JSON
  python3 - <<'PY'
import json,glob,re,sys
vals=set()
for f in glob.glob('docs/reviews/perf/*benchmarkData*.json'):
    d=json.load(open(f))
    for b in d.get('benchmarks',[]):
        for m in list(b.get('metrics',{}).values())+list(b.get('sampledMetrics',{}).values()):
            def walk(x):
                if isinstance(x,bool): return
                if isinstance(x,(int,float)): vals.add(round(float(x),1))
                elif isinstance(x,list):
                    for y in x: walk(y)
                elif isinstance(x,dict):
                    for y in x.values(): walk(y)
            walk(m)
try: rep=open('docs/reviews/PERF_REPORT.md').read()
except FileNotFoundError: print("PASS  13 no PERF_REPORT.md (nothing to cross-check)"); sys.exit(0)
rows=[l for l in rep.splitlines() if l.strip().startswith('|') and re.search(r'\d+(\.\d+)?\s*ms',l)]
missing=[]
for l in rows:
    for x in re.findall(r'(\d+(?:\.\d+)?)\s*ms',l):
        if round(float(x),1) not in vals: missing.append(x)
if not vals and rows: print("FAIL  13 report quotes %d ms values but no genuine benchmark JSON exists"%len(rows)); sys.exit(3)
if missing: print("FAIL  13 %d ms value(s) in PERF_REPORT.md not found in genuine JSON (e.g. %s)"%(len(missing),', '.join(sorted(set(missing))[:8]))); sys.exit(3)
print("PASS  13 every ms value in PERF_REPORT.md is present in a genuine JSON file"); sys.exit(0)
PY
  [ $? -ne 0 ] && FAILS=$((FAILS+1))
fi

# 14. Forbidden self-praise wording in docs/reviews and release notes
n=$(grep -rniE '10/10|zero jank|flagship|perfect(ion)?\b|buttery' docs/reviews docs/releases 2>/dev/null | grep -v "verify_round" | wc -l)
[ "$n" -eq 0 ] && pass "14 no self-praise wording in docs/reviews or docs/releases" || warn "14 $n line(s) of self-praise wording in docs (remove)"

# 15. Working tree clean
[ -z "$(git status --porcelain | grep -v "scripts/verify_round.sh")" ] && pass "15 working tree clean" || fail "15 uncommitted changes"

echo "------------------------------------------------------------"
echo "FAIL: $FAILS   WARN: $WARNS"
[ "$FAILS" -eq 0 ]
